"""Build English standalone report and Chinese canvas from audited results, offline."""
import argparse,base64,html,json
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def main(root,scope):
    d=root/'execution_20261112'/(scope+'_analysis');s=json.loads((d/'summary.json').read_text());c=s['conditions'];metrics=s['comparisons']
    fig,ax=plt.subplots(figsize=(8,4.7));x=[0,1];w=.30
    for label,keys,offset,color in [('With video',['video_single','video_context7'],-w/2,'#276e68'),('Without video',['novideo_single','novideo_context7'],w/2,'#87949e')]:
        values=[c[k]['accuracy_pct'] for k in keys];bars=ax.bar([v+offset for v in x],values,width=w,label=label,color=color)
        for bar,value in zip(bars,values):ax.text(bar.get_x()+bar.get_width()/2,value+.8,f'{value:.2f}%',ha='center',fontsize=10)
    ax.set(xticks=x,xticklabels=['Target alone','Target + 7 reference questions'],ylabel='Target accuracy (%)',xlabel='Reference-context condition',ylim=(0,85),title=f'Argon · HD-EPIC · {s["targets"]} matched targets / {s["videos"]} videos');ax.legend(frameon=False);ax.spines[['top','right']].set_visible(False)
    fig.text(.5,.015,'Saved with-video outcomes reused; new without-video calls answer ONLY the target.\nSource: frozen study inputs and successful API responses · November 2026.',ha='center',fontsize=9);fig.tight_layout(rect=(0,.08,1,1));fig.savefig(d/'accuracy.png',dpi=180);fig.savefig(d/'accuracy.svg');plt.close(fig)
    esc=html.escape;fmt=lambda v:f'{v:.2f}'
    labels={'video_single':'With video · target alone','video_context7':'With video · +7 references','novideo_single':'Without video · target alone','novideo_context7':'Without video · +7 references'}
    def download(name,label):
        p=d/name;encoded=base64.b64encode(p.read_bytes()).decode();mime='application/gzip' if name.endswith('.gz') else 'application/json' if name.endswith('.json') else 'text/csv'
        return f'<a download="{name}" href="data:{mime};base64,{encoded}">{label}</a>'
    rows=''.join(f'<tr><td>{labels[k]}</td><td>{v["correct"]}/{v["targets"]}</td><td>{fmt(v["accuracy_pct"])}%</td></tr>' for k,v in c.items())
    contrasts=''.join(f'<tr><td>{esc(k)}</td><td>{fmt(v["estimate_pp"])} pp</td><td>{fmt(v["paired_video_bootstrap_95_pp"][0])} to {fmt(v["paired_video_bootstrap_95_pp"][1])}</td></tr>' for k,v in metrics.items())
    cost=s['usage_cost'];lat=s['latency'];D=metrics['interaction_D'];lo,hi=D['paired_video_bootstrap_95_pp']
    interpretation=('The context benefit is larger with video in this saved-output comparison; this supports a visual-input-dependent component, without isolating visual reasoning or excluding clues that help locate frames.' if lo>0 else 'The context benefit is larger without video in this saved-output comparison; inspect text/option cues and response bias before drawing a mechanism conclusion.' if hi<0 else 'The interval for the difference in context benefits includes zero. These data do not distinguish the two benefits precisely; this is not evidence that they are equivalent.')
    usage_rows=''.join(f'<tr><td>{esc(k)}</td><td>{v["calls"]}</td><td>{v["prompt_tokens"]:,}</td><td>{v["completion_including_reasoning"]:,}</td><td>${v["estimated_usd"]:.4f}</td><td>{v["median_api_latency_s"]:.2f} s</td></tr>' for k,v in s.get('new_call_conditions',{}).items())
    doc=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Argon context × video control</title><style>body{{font:16px system-ui;max-width:1000px;margin:40px auto;padding:0 20px;color:#26333b}}h1{{font-size:28px}}h2{{font-size:20px;margin-top:32px}}p{{line-height:1.6}}svg{{width:100%;height:auto}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{padding:11px;text-align:left;border-bottom:1px solid #d9e0e4}}.muted{{color:#65717a;font-size:14px}}.downloads{{display:flex;gap:20px;flex-wrap:wrap}}details{{margin-top:24px}}code{{overflow-wrap:anywhere}}</style>
    <p class="muted">HD-EPIC · Gemini 4 Argon · {scope.upper()} · New no-video calls completed 12 November 2026</p><h1>Do reference questions help more when video is available?</h1><p>{s['targets']} identical targets across four conditions. Only the target is answered; reference questions retain their options. All {s['new_calls']} new calls succeeded with valid answers.</p>
    {(d/'accuracy.svg').read_text()}<table><thead><tr><th>Condition</th><th>Correct / targets</th><th>Accuracy</th></tr></thead><tbody>{rows}</tbody></table>
    <h2>Primary result: difference in context benefits</h2><p><strong>D = {fmt(D['estimate_pp'])} pp</strong> · paired video bootstrap 95% interval [{fmt(lo)}, {fmt(hi)}].</p><p>D = (with-video +7 minus with-video alone) − (without-video +7 minus without-video alone).</p><p>{interpretation}</p><table><thead><tr><th>Paired comparison</th><th>Change</th><th>95% interval (pp)</th></tr></thead><tbody>{contrasts}</tbody></table>
    <h2>New-call usage, estimated cost and latency</h2><p><strong>${cost['estimated_usd']:.4f}</strong> estimated cost · {cost['prompt_tokens']:,} prompt tokens · {cost['completion_including_reasoning']:,} completion tokens, including {cost['reasoning_tokens']:,} reasoning tokens (counted once).</p><p>Median successful request latency: <strong>{lat['median_request_s']:.2f} s</strong>; p95 {lat['p95_request_s']:.2f} s. These are API roundtrips, excluding queues and downtime.</p><p class="muted">New no-video calls only; prior video outcomes are reused. Frozen historical rates estimate ($2/M input, $0.10/M cached input, $10/M completion). No billing balance or invoice validation. {s.get("unknown_billing_attempts",0)} archived failed attempt(s) have unknown billing and are excluded from this successful-call estimate.</p>
    <table><thead><tr><th>No-video condition</th><th>Calls</th><th>Input tokens</th><th>Output incl. reasoning</th><th>Estimated cost</th><th>Median API latency</th></tr></thead><tbody>{usage_rows}</tbody></table><details><summary>Setup, uncertainty and evidence</summary><p>Native Vertex Global; returned model alias gemini-4-argon; MEDIUM thinking; max output 32,768; JSON response. Same system/user text as the historical conditions, including the video marker; video media removed. Invalid answers count wrong; provider failures are separate. Per-recording paired bootstrap: 10,000 draws, seed 20261112; no multiple-comparison correction.</p><ul>{''.join('<li>'+esc(x)+'</li>' for x in s['limitations'])}</ul><p>Historical comparison SHA256: <code>{s['provenance']['historical_paired_csv_sha256']}</code></p></details>
    <h2>Downloads</h2><div class="downloads">{download('paired_predictions.csv','Paired answers CSV')}{download('per_call.csv','New-call usage CSV')}{download('summary.json','Analysis JSON')}{download('experiment_log.jsonl.gz','Exact inputs + raw outputs')}</div></html>'''
    (d/'report.html').write_text(doc)
    canvas='''import {Stack,H1,H2,Text,useHostTheme} from "cursor/canvas";
const s=DATA;
export default function Report(){const t=useHostTheme();const c=s.conditions;const keys=['video_single','video_context7','novideo_single','novideo_context7'] as const;const labels=['有影片・單題','有影片・＋7參考題','無影片・單題','無影片・＋7參考題'];const D=s.comparisons.interaction_D;return <Stack gap={18} style={{padding:24,maxWidth:1000,background:t.bg.editor,color:t.text.primary}}><H1>Argon：參考題的幫助是否依賴影片？</H1><Text>HD-EPIC・SCOPE・同一批 {s.targets} 題／{s.videos} 支影片；只回答目標題。新無影片呼叫 {s.new_calls} 筆，全部通過格式檢查。</Text><svg viewBox="0 0 850 330" role="img" aria-label="四個條件的目標題準確率" style={{width:'100%'}}>{[0,20,40,60,80,100].map(v=><g key={v}><line x1="65" x2="830" y1={260-v*2} y2={260-v*2} stroke={t.stroke.tertiary}/><text x="54" y={264-v*2} textAnchor="end" fill={t.text.secondary} fontSize="12">{v}%</text></g>)}{keys.map((k,i)=><g key={k}><rect x={100+i*185} y={260-c[k].accuracy_pct*2} width="115" height={c[k].accuracy_pct*2} fill={i<2?t.accent.primary:t.fill.secondary}/><text x={157+i*185} y={249-c[k].accuracy_pct*2} textAnchor="middle" fill={t.text.primary} fontSize="16">{c[k].accuracy_pct.toFixed(2)}%</text><text x={157+i*185} y="286" textAnchor="middle" fill={t.text.primary} fontSize="13">{labels[i]}</text></g>)}<text x="450" y="318" textAnchor="middle" fill={t.text.secondary} fontSize="12">X：提問條件　Y：目標準確率（%）・來源：已保存有影片答案與本次無影片 API 輸出</text></svg><H2>有影片的 context 增益 − 無影片的 context 增益：{D.estimate_pp.toFixed(2)} 個百分點</H2><Text>配對影片 bootstrap 95% 區間：{D.paired_video_bootstrap_95_pp.map(v=>v.toFixed(2)).join(' ～ ')}。有影片增益 {s.comparisons.video_context_gain.estimate_pp.toFixed(2)} 點；無影片增益 {s.comparisons.novideo_context_gain.estimate_pp.toFixed(2)} 點。</Text><Text>{D.paired_video_bootstrap_95_pp[0]>0?'這批結果支持參考題的部分幫助依賴影片；仍不能排除時間選項提示或定位線索，也不等於證明視覺推理改善。':D.paired_video_bootstrap_95_pp[1]<0?'這批結果中無影片的參考題增益更大，應先檢查文字線索與答案偏好。':'區間包含0，目前無法精確區分兩種增益；不能把這解釋為兩者相同。'}</Text><H2>用量與速度</H2><Text>新增呼叫估算 ${s.usage_cost.estimated_usd.toFixed(4)}；輸入 {s.usage_cost.prompt_tokens.toLocaleString()} tokens；輸出含 reasoning {s.usage_cost.completion_including_reasoning.toLocaleString()} tokens。API latency 中位數 {s.latency.median_request_s.toFixed(2)} 秒，p95 {s.latency.p95_request_s.toFixed(2)} 秒，排除排隊與斷線等待。</Text><Text>成本依歷史固定單價估算，非帳單；另有 {s.unknown_billing_attempts} 次失敗嘗試費用未知，未計入成功成本。沿用歷史有影片答案；相同模型別名不保證供應商內部未更新。兩種 prompt 也有格式與目標位置差異。探索性小樣本，沒有多重比較校正。</Text></Stack>}
'''
    canvas=canvas.replace('DATA',json.dumps({k:v for k,v in s.items() if k!='raw_call_hashes'},ensure_ascii=False)).replace('SCOPE',scope.upper())
    (Path('/Users/jeremy/.cursor/projects/app/canvases')/'HD-EPIC-Argon-reference-video-control.canvas.tsx').write_text(canvas)
    print(d/'report.html')
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--scope',choices=['pilot','full'],default='full');a=p.parse_args();main(a.root,a.scope)
